package vn.edu.eaut.lab6.store;
import vn.edu.eaut.lab6.model.Student; import java.util.*;
public class StudentStore { private static final List<Student> students=new ArrayList<>();
 public static synchronized void initSampleData(){if(!students.isEmpty())return; students.add(new Student("SV001","Nguyen Van An","DCCNTT12","an@example.com"));students.add(new Student("SV002","Tran Thi Binh","DCCNTT12","binh@example.com"));students.add(new Student("SV003","Le Van Cuong","DCCNTT13","cuong@example.com"));students.add(new Student("SV004","Pham Thi Dung","DCCNTT13","dung@example.com"));students.add(new Student("SV005","Hoang Van Em","DCCNTT14","em@example.com"));}
 public static synchronized List<Student> findAll(){return new ArrayList<>(students);} public static synchronized void add(Student s){students.add(s);} public static synchronized Student findById(String id){for(Student s:students)if(s.getId().equalsIgnoreCase(id))return s;return null;} public static synchronized boolean delete(String id){return students.removeIf(s->s.getId().equalsIgnoreCase(id));} public static synchronized boolean update(Student u){Student s=findById(u.getId());if(s==null)return false;s.setName(u.getName());s.setClassName(u.getClassName());s.setEmail(u.getEmail());return true;} public static synchronized List<Student> search(String k){k=k==null?"":k.trim().toLowerCase();List<Student> r=new ArrayList<>();for(Student s:students)if(k.isEmpty()||s.getName().toLowerCase().contains(k))r.add(s);return r;} public static synchronized int count(){return students.size();} public static synchronized int countByClass(String c){int n=0;for(Student s:students)if(s.getClassName().equalsIgnoreCase(c))n++;return n;} public static synchronized List<String> classes(){List<String>r=new ArrayList<>();for(Student s:students)if(!r.contains(s.getClassName()))r.add(s.getClassName());return r;}}
